param([Parameter(Mandatory)][string]$Source)
$ErrorActionPreference='Stop'
Add-Type -TypeDefinition ('using System;using System.Security.Principal;using System.Security.AccessControl;'+[IO.File]::ReadAllText($Source))
$admin=[Security.Principal.SecurityIdentifier]::new('S-1-5-32-544');$system=[Security.Principal.SecurityIdentifier]::new('S-1-5-18');$vm=[Security.Principal.SecurityIdentifier]::new('S-1-5-83-1-1-2-3-4');$other=[Security.Principal.SecurityIdentifier]::new('S-1-5-83-1-4-3-2-1');$worker=[Security.Principal.SecurityIdentifier]::new('S-1-15-3-1024-2268835264-3721307629-241982045-173645152-1490879176-104643441-2915960892-1612460704')
function Base([bool]$directory){$acl=if($directory){[Security.AccessControl.DirectorySecurity]::new()}else{[Security.AccessControl.FileSecurity]::new()};$acl.SetOwner($admin);foreach($sid in @($admin,$system,$vm,$worker)){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,[Security.AccessControl.FileSystemRights]::FullControl,[Security.AccessControl.AccessControlType]::Allow))};return $acl}
function Reject($acl,[bool]$directory){$rejected=$false;try{[MuRecoveryPermissions]::Validate($acl,$vm,$directory)}catch{if($_.Exception.GetBaseException() -isnot [UnauthorizedAccessException]){throw};$rejected=$true};if(-not $rejected){throw 'Unexpected recovery permission authority was accepted'}}
foreach($directory in @($true,$false)){
 $acl=Base $directory;[MuRecoveryPermissions]::Validate($acl,$vm,$directory)
 foreach($sid in @($other,[Security.Principal.SecurityIdentifier]::new('S-1-5-21-1-2-3-1001'),[Security.Principal.SecurityIdentifier]::new('S-1-1-0'),[Security.Principal.SecurityIdentifier]::new('S-1-15-3-1024-1-2-3-4-5-6-7-8'))){$changed=Base $directory;$changed.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,[Security.AccessControl.FileSystemRights]::Read,[Security.AccessControl.AccessControlType]::Allow));Reject $changed $directory}
 $acl=Base $directory;$acl.SetOwner($other);Reject $acl $directory
}
$acl=Base $true;$service=[Security.Principal.SecurityIdentifier]::new('S-1-5-83-0');$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($service,([Security.AccessControl.FileSystemRights]::Read -bor [Security.AccessControl.FileSystemRights]::WriteData -bor [Security.AccessControl.FileSystemRights]::AppendData -bor [Security.AccessControl.FileSystemRights]::Synchronize),[Security.AccessControl.AccessControlType]::Allow));$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-3-0'),[Security.AccessControl.FileSystemRights]::FullControl,[Security.AccessControl.InheritanceFlags]::ContainerInherit,[Security.AccessControl.PropagationFlags]::InheritOnly,[Security.AccessControl.AccessControlType]::Allow));[MuRecoveryPermissions]::Validate($acl,$vm,$true)
$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($service,[Security.AccessControl.FileSystemRights]::ChangePermissions,[Security.AccessControl.AccessControlType]::Allow));Reject $acl $true
$acl=Base $false;$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($service,[Security.AccessControl.FileSystemRights]::Read,[Security.AccessControl.AccessControlType]::Allow));Reject $acl $false
[Console]::Write('Recovery permission policy accepted exact service identities and rejected foreign/ordinary/broad identities')
